using UnityEngine;using UnityEngine.UI; namespace Mojinloop.Combat { public sealed class DamagePopup:MonoBehaviour { Text label;float life;public void Show(int damage,Vector3 world,Canvas canvas){label=GetComponent<Text>();label.text=damage.ToString();transform.SetParent(canvas.transform,false);transform.position=Camera.main.WorldToScreenPoint(world+Vector3.up*.7f);life=.55f;gameObject.SetActive(true);}void Update(){if(life<=0)return;life-=Time.unscaledDeltaTime;transform.position+=Vector3.up*35f*Time.unscaledDeltaTime;label.color=new Color(1,.85f,.2f,Mathf.Clamp01(life*2));if(life<=0)Destroy(gameObject);} } }
